 private static final android.util.LruCache<String,Bitmap> ART_CACHE=new android.util.LruCache<String,Bitmap>(32);
 private static Bitmap decodeGiftBitmap(Context c,String id,int targetPx){
  int resId=c.getResources().getIdentifier("gift_"+id,"drawable",c.getPackageName());
  if(resId==0)return null;
  try{
   BitmapFactory.Options o=new BitmapFactory.Options();
   o.inJustDecodeBounds=true;o.inScaled=false;
   BitmapFactory.decodeResource(c.getResources(),resId,o);
   if(o.outWidth<=0||o.outHeight<=0)return null;
   o.inSampleSize=MediaImageLoader.calculateInSampleSize(o.outWidth,o.outHeight,targetPx);
   o.inJustDecodeBounds=false;o.inScaled=false;
   return BitmapFactory.decodeResource(c.getResources(),resId,o);
  }catch(Throwable ignored){return null;}
 }
 private static Bitmap cachedArtBitmap(Context c,String id){return cachedArtBitmap(c,id,160);}
 private static Bitmap cachedArtBitmap(Context c,String id,int targetPx){
  String key=id+"@"+targetPx;
  Bitmap cached=ART_CACHE.get(key);
  if(cached!=null&&!cached.isRecycled())return cached;
  Bitmap decoded=decodeGiftBitmap(c,id,targetPx);
  if(decoded!=null)ART_CACHE.put(key,decoded);
  return decoded;
 }
 private void loadSoundAsset(Context appCtx,String name){
  if(closed)return;
  String path="gifts/"+name+".wav";
  try{
   int id=-1;
   try(android.content.res.AssetFileDescriptor fd=appCtx.getAssets().openFd(path)){
    synchronized(soundLock){if(closed)return;id=sounds.load(fd,1);}
   }catch(IOException compressed){
    File file=new File(appCtx.getCacheDir(),"gift-"+name+".wav");
    if(!file.exists()||file.length()==0){
     File tmp=new File(appCtx.getCacheDir(),"gift-"+name+".wav.tmp");
     try(InputStream in=appCtx.getAssets().open(path);OutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
     if(!tmp.renameTo(file))tmp.delete();
    }
    synchronized(soundLock){if(closed)return;id=sounds.load(file.getAbsolutePath(),1);}
   }
   if(id>0)samples.put(name,id);
  }catch(Throwable ignored){}
 }
