 int version(){return priceVersion;}
 int quantity(){return selectedQuantity;}
 String comboId(){return SystemClock.uptimeMillis()<=comboExpiresAt?currentComboId:"";}
 String ensureComboId(String giftId){
  if(giftId==null||!comboable.contains(giftId)){currentComboId="";comboKey="";comboExpiresAt=0L;return "";}
  long now=SystemClock.uptimeMillis();
  String key=giftId+":"+(targetUserId==null?"":targetUserId);
  if(!key.equals(comboKey)||currentComboId.isEmpty()||now>comboExpiresAt){comboKey=key;currentComboId="combo_"+giftId+"_"+Long.toHexString(now);}
  comboExpiresAt=now+4500L;
  return currentComboId;
 }
