 void setTargets(JSONArray participants,String hostId,String hostName){
  stageTargets=participants!=null?participants:new JSONArray();
  String nextHost=hostId!=null?hostId:"";
  boolean hostChanged=!nextHost.equals(currentHostId);
  currentHostId=nextHost;
  boolean validTarget=false;
  if(!hostChanged&&!targetUserId.isEmpty()){
   if(targetUserId.equals(nextHost))validTarget=true;
   for(int i=0;i<stageTargets.length();i++){
    JSONObject p=stageTargets.optJSONObject(i);
    if(p!=null&&targetUserId.equals(p.optString("userId",p.optString("id")))){validTarget=true;break;}
   }
  }
  if(!validTarget){
   targetUserId=nextHost;
   targetUserName=hostName!=null?hostName:"";
  }
 }
