 void show(FrameLayout layer,String id,String from,boolean audible){show(layer,id,from,1,audible);}
 void show(FrameLayout layer,String id,String from,int comboCount,boolean audible){if(closed||name(id)==null||layer==null)return;String tier=tiers.containsKey(id)?tiers.get(id):"small";boolean big="large".equals(tier)||"legendary".equals(tier);if(reduceEffects){if(audible){if(big)playSequence(id);else play(id);}return;}if("legendary".equals(tier)){for(Effect e:active)if("legendary".equals(e.tier)){if(audible)playSequence(id);return;}}while(active.size()>=2)active.removeFirst().finish();Effect effect=new Effect(activity,id,from,tier,Math.max(1,comboCount));effect.end=()->{active.remove(effect);layer.removeView(effect);};active.add(effect);layer.addView(effect,new FrameLayout.LayoutParams(-1,-1));effect.start();if(audible){if(big)playSequence(id);else play(id);}}
 void soundOnly(String id,boolean audible){if(audible)play(id);}
 private void play(String id){AudioManager audio=(AudioManager)activity.getSystemService(Context.AUDIO_SERVICE);Integer sample=samples.get(id);if(!soundOn||closed||sample==null||!loaded.contains(sample)||audio==null||audio.getRingerMode()!=AudioManager.RINGER_MODE_NORMAL||audio.getStreamVolume(AudioManager.STREAM_MUSIC)==0||SystemClock.uptimeMillis()-lastSound<450)return;lastSound=SystemClock.uptimeMillis();synchronized(soundLock){if(closed)return;int stream=sounds.play(sample,.38f,.38f,1,0,1);if(stream!=0){streams.addLast(stream);while(streams.size()>2)sounds.stop(streams.removeFirst());}}}
 private void playCue(String id){AudioManager audio=(AudioManager)activity.getSystemService(Context.AUDIO_SERVICE);Integer sample=samples.get(id);if(!soundOn||closed||sample==null||!loaded.contains(sample)||audio==null||audio.getRingerMode()!=AudioManager.RINGER_MODE_NORMAL||audio.getStreamVolume(AudioManager.STREAM_MUSIC)==0)return;synchronized(soundLock){if(closed)return;int stream=sounds.play(sample,.45f,.45f,1,0,1);if(stream!=0){streams.addLast(stream);while(streams.size()>4)sounds.stop(streams.removeFirst());}}}
 private static String[] sequence(String id){switch(id){case "car":return new String[]{"car_intro:0","car_engine:420"};case "yacht":return new String[]{"yacht_waves:0","yacht_horn:1300"};case "castle":return new String[]{"castle_intro:0","castle_impact:950","castle_fanfare:1900"};default:return new String[]{id+":0"};}}
 private void playSequence(String id){if(!soundOn||closed)return;for(String cue:sequence(id)){String[] part=cue.split(":");int delay=Integer.parseInt(part[1]);if(delay<=0)playCue(part[0]);else cueHandler.postDelayed(()->playCue(part[0]),delay);}}
 void stopVisuals(){cueHandler.removeCallbacksAndMessages(null);while(!active.isEmpty())active.removeFirst().finish();}
 void close(){synchronized(soundLock){if(closed)return;closed=true;}if(dialog!=null)try{dialog.dismiss();}catch(Exception ignored){}stopVisuals();cueHandler.removeCallbacksAndMessages(null);synchronized(soundLock){try{sounds.release();}catch(Exception ignored){}}}

