 static void star(Canvas c,Paint p,float x,float y,float size,int color){Path path=new Path();for(int i=0;i<10;i++){double a=-Math.PI/2+i*Math.PI/5;float r=size*(i%2==0?.5f:.22f),xx=x+(float)Math.cos(a)*r,yy=y+(float)Math.sin(a)*r;if(i==0)path.moveTo(xx,yy);else path.lineTo(xx,yy);}path.close();p.setShader(null);p.setColor(color);c.drawPath(path,p);}
