  int particleCount(){int base="legendary".equals(tier)?48:"large".equals(tier)?40:"medium".equals(tier)?26:18;return Math.min(64,base+Math.min(16,(combo-1)*4));}
  float heroSizeDp(){return "legendary".equals(tier)?230:"large".equals(tier)?200:"medium".equals(tier)?170:140;}
